fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Assume end < v.len()
    let mut max_idx = 0;
    let mut max_val = v[0];
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }
    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Assume start < v.len()
    let mut min_idx = start;
    let mut min_val = v[start];
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }
    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, there is no suffix, so the condition is vacuously true.
    if p + 1 >= v.len() {
        return true;
    }
    let (max_pref, _) = find_max_in_prefix(v, p);
    let (min_suff, _) = find_min_in_suffix(v, p + 1);
    max_pref < min_suff
}

