        assert_eq!(find_min_in_suffix(&a, 0), (1, 1));
        assert_eq!(find_min_in_suffix(&a, 1), (1, 1));
        assert_eq!(find_min_in_suffix(&a, 2), (2, 3));
        assert_eq!(find_min_in_suffix(&a, 3), (2, 3));
